// generateAssistantTitle is a handler for POST /webapi/assistant/title/summary.
func (h *Handler) generateAssistantTitle(_ http.ResponseWriter, r *http.Request,
	_ httprouter.Params, sctx *SessionContext,
) (any, error) {
	var req generateAssistantTitleRequest
	if err := httplib.ReadJSON(r, &req); err != nil {
		return nil, trace.Wrap(err)
	}

	authClient, err := sctx.GetClient()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if err := checkAssistEnabled(authClient, r.Context()); err != nil {
		return nil, trace.Wrap(err)
	}

	client, err := assist.NewClient(r.Context(), h.cfg.ProxyClient,
		h.cfg.ProxySettings, h.cfg.OpenAIConfig)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	titleSummary, err := client.GenerateSummary(r.Context(), req.Message)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	conversationInfo := &conversationInfo{
		Title: titleSummary,
	}

	// We only want to emmit
	if modules.GetModules().Features().Cloud {
		go func() {
			ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
			defer cancel()
			class, err := client.ClassifyMessage(ctx, req.Message, assist.MessageClasses)
			if err != nil {
				return
			}
			h.log.Debugf("message classified as '%s'", class)
			// TODO(shaka): emit event here to report the message class
		}()

	}

	return conversationInfo, nil
}

func (h *Handler) assistant(w http.ResponseWriter, r *http.Request, _ httprouter.Params,
	sctx *SessionContext, site reversetunnelclient.RemoteSite,
) (any, error) {
	if err := runAssistant(h, w, r, sctx, site); err != nil {
		h.log.Warn(trace.DebugReport(err))
		return nil, trace.Wrap(err)
	}

	return nil, nil
}

func checkAssistEnabled(a auth.ClientI, ctx context.Context) error {
	enabled, err := a.IsAssistEnabled(ctx)
	if err != nil {
		return trace.Wrap(err)
	}
	if !enabled.Enabled {
		return trace.AccessDenied("Assist is not enabled")
	}

	return nil
}

// runAssistant upgrades the HTTP connection to a websocket and starts a chat loop.
func runAssistant(h *Handler, w http.ResponseWriter, r *http.Request,
	sctx *SessionContext, site reversetunnelclient.RemoteSite,
) (err error) {
	q := r.URL.Query()
	conversationID := q.Get("conversation_id")
	if conversationID == "" {
		return trace.BadParameter("conversation ID is required")
	}

	authClient, err := sctx.GetClient()
	if err != nil {
		return trace.Wrap(err)
	}

	if err := checkAssistEnabled(authClient, r.Context()); err != nil {
		return trace.Wrap(err)
	}

	ctx, err := h.cfg.SessionControl.AcquireSessionContext(r.Context(), sctx, sctx.GetUser(), h.cfg.ProxyWebAddr.Addr, r.RemoteAddr)
	if err != nil {
		return trace.Wrap(err)
	}

	authAccessPoint, err := site.CachingAccessPoint()
	if err != nil {
		h.log.WithError(err).Debug("Unable to get auth access point.")
		return trace.Wrap(err)
	}

	netConfig, err := authAccessPoint.GetClusterNetworkingConfig(ctx)
	if err != nil {
		h.log.WithError(err).Debug("Unable to fetch cluster networking config.")
		return trace.Wrap(err)
	}

	upgrader := websocket.Upgrader{
		ReadBufferSize:  1024,
		WriteBufferSize: 1024,
		CheckOrigin:     func(r *http.Request) bool { return true },
	}

	ws, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		errMsg := "Error upgrading to websocket"
		h.log.WithError(err).Error(errMsg)
		http.Error(w, errMsg, http.StatusInternalServerError)
		return nil
	}

	// Note: This time should be longer than OpenAI response time.
	keepAliveInterval := netConfig.GetKeepAliveInterval()
	err = ws.SetReadDeadline(deadlineForInterval(keepAliveInterval))
	if err != nil {
		h.log.WithError(err).Error("Error setting websocket readline")
		return nil
	}
	defer func() {
		closureReason := websocket.CloseNormalClosure
		closureMsg := ""
		if err != nil {
			h.log.WithError(err).Error("Error in the Assistant loop")
			_ = ws.WriteJSON(&assistantMessage{
				Type:        assist.MessageKindError,
				Payload:     "An error has occurred. Please try again later.",
				CreatedTime: h.clock.Now().UTC().Format(time.RFC3339),
			})
			// Set server error code and message: https://datatracker.ietf.org/doc/html/rfc6455#section-7.4.1
			closureReason = websocket.CloseInternalServerErr
			closureMsg = err.Error()
		}
		// Send the close message to the client and close the connection
		if err := ws.WriteControl(websocket.CloseMessage,
			websocket.FormatCloseMessage(closureReason, closureMsg),
			time.Now().Add(time.Second),
		); err != nil {
			h.log.Warnf("Failed to write close message: %v", err)
		}
		if err := ws.Close(); err != nil {
			h.log.Warnf("Failed to close websocket: %v", err)
		}
	}()

	// Update the read deadline upon receiving a pong message.
	ws.SetPongHandler(func(_ string) error {
		ws.SetReadDeadline(deadlineForInterval(keepAliveInterval))
		return nil
	})

	ws.SetCloseHandler(func(code int, text string) error {
		h.log.Debugf("closing assistant websocket: %v %v", code, text)
		return nil
	})

	go startPingLoop(ctx, ws, keepAliveInterval, h.log, nil)

	assistClient, err := assist.NewClient(ctx, h.cfg.ProxyClient,
		h.cfg.ProxySettings, h.cfg.OpenAIConfig)
	if err != nil {
		return trace.Wrap(err)
	}

	chat, err := assistClient.NewChat(ctx, authClient, authClient.EmbeddingClient(), conversationID, sctx.GetUser())
	if err != nil {
		return trace.Wrap(err)
	}

	// onMessageFn is called when a message is received from the OpenAI API.
	onMessageFn := func(kind assist.MessageType, payload []byte, createdTime time.Time) error {
		msg := &assistantMessage{
			Type:        kind,
			Payload:     string(payload),
			CreatedTime: createdTime.Format(time.RFC3339),
		}

		return trace.Wrap(ws.WriteJSON(msg))
	}

	if chat.IsNewConversation() {
		// new conversation, generate a hello message
		if _, err := chat.ProcessComplete(ctx, onMessageFn, ""); err != nil {
			return trace.Wrap(err)
		}
	}

	for {
		_, payload, err := ws.ReadMessage()
		if err != nil {
			if err == io.EOF || websocket.IsCloseError(err, websocket.CloseAbnormalClosure,
				websocket.CloseGoingAway, websocket.CloseNormalClosure) {
				break
			}
			return trace.Wrap(err)
		}

		var wsIncoming assistantMessage
		if err := json.Unmarshal(payload, &wsIncoming); err != nil {
			return trace.Wrap(err)
		}

		// We can not know how many tokens we will consume in advance.
		// Try to consume a small amount of tokens first.
		const lookaheadTokens = 100
		if !h.assistantLimiter.AllowN(time.Now(), lookaheadTokens) {
			err := onMessageFn(assist.MessageKindError, []byte("You have reached the rate limit. Please try again later."), h.clock.Now().UTC())
			if err != nil {
				return trace.Wrap(err)
			}
			continue
		}

		//TODO(jakule): Should we sanitize the payload?
		usedTokens, err := chat.ProcessComplete(ctx, onMessageFn, wsIncoming.Payload)
		if err != nil {
			return trace.Wrap(err)
		}

		// Once we know how many tokens were consumed for prompt+completion,
		// consume the remaining tokens from the rate limiter bucket.
		extraTokens := usedTokens.Prompt + usedTokens.Completion - lookaheadTokens
		if extraTokens < 0 {
			extraTokens = 0
		}
		h.assistantLimiter.ReserveN(time.Now(), extraTokens)

		usageEventReq := &proto.SubmitUsageEventRequest{
			Event: &usageeventsv1.UsageEventOneOf{
				Event: &usageeventsv1.UsageEventOneOf_AssistCompletion{
					AssistCompletion: &usageeventsv1.AssistCompletionEvent{
						ConversationId:   conversationID,
						TotalTokens:      int64(usedTokens.Prompt + usedTokens.Completion),
						PromptTokens:     int64(usedTokens.Prompt),
						CompletionTokens: int64(usedTokens.Completion),
					},
				},
			},
		}
		if err := authClient.SubmitUsageEvent(r.Context(), usageEventReq); err != nil {
			h.log.WithError(err).Warn("Failed to emit usage event")
		}
	}

	h.log.Debug("end assistant conversation loop")
	return nil
}

	if openaiCfg != nil {
		return ai.NewClientFromConfig(*openaiCfg), nil
	}
	return ai.NewClient(apiKey), nil
}

// onMessageFunc is a function that is called when a message is received.
type onMessageFunc func(kind MessageType, payload []byte, createdTime time.Time) error

// ProcessComplete processes the completion request and returns the number of tokens used.
func (c *Chat) ProcessComplete(ctx context.Context, onMessage onMessageFunc, userInput string,
) (*model.TokensUsed, error) {
	var tokensUsed *model.TokensUsed
	progressUpdates := func(update *model.AgentAction) {
		payload, err := json.Marshal(update)
		if err != nil {
			log.WithError(err).Debugf("Failed to marshal progress update: %v", update)
			return
		}

		if err := onMessage(MessageKindProgressUpdate, payload, c.assist.clock.Now().UTC()); err != nil {
			log.WithError(err).Debugf("Failed to send progress update: %v", update)
			return
		}
	}

	// If data might have been inserted into the chat history, we want to
	// refresh and get the latest data before querying the model.
	if c.potentiallyStaleHistory {
		if err := c.reloadMessages(ctx); err != nil {
			return nil, trace.Wrap(err)
		}
	}

	// query the assistant and fetch an answer
	message, err := c.chat.Complete(ctx, userInput, progressUpdates)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// write the user message to persistent storage and the chat structure
	c.chat.Insert(openai.ChatMessageRoleUser, userInput)

	// Do not write empty messages to the database.
	if userInput != "" {
		if err := c.assistService.CreateAssistantMessage(ctx, &assist.CreateAssistantMessageRequest{
			Message: &assist.AssistantMessage{
				Type:        string(MessageKindUserMessage),
				Payload:     userInput, // TODO(jakule): Sanitize the payload
				CreatedTime: timestamppb.New(c.assist.clock.Now().UTC()),
			},
			ConversationId: c.ConversationID,
			Username:       c.Username,
		}); err != nil {
			return nil, trace.Wrap(err)
		}
	}

	switch message := message.(type) {
	case *model.Message:
		tokensUsed = message.TokensUsed
		c.chat.Insert(openai.ChatMessageRoleAssistant, message.Content)

		// write an assistant message to persistent storage
		protoMsg := &assist.CreateAssistantMessageRequest{
			ConversationId: c.ConversationID,
			Username:       c.Username,
			Message: &assist.AssistantMessage{
				Type:        string(MessageKindAssistantMessage),
				Payload:     message.Content,
				CreatedTime: timestamppb.New(c.assist.clock.Now().UTC()),
			},
		}

		if err := c.assistService.CreateAssistantMessage(ctx, protoMsg); err != nil {
			return nil, trace.Wrap(err)
		}

		if err := onMessage(MessageKindAssistantMessage, []byte(message.Content), c.assist.clock.Now().UTC()); err != nil {
			return nil, trace.Wrap(err)
		}
	case *model.StreamingMessage:
		tokensUsed = message.TokensUsed
		var text strings.Builder
		defer onMessage(MessageKindAssistantPartialFinalize, nil, c.assist.clock.Now().UTC())
		for part := range message.Parts {
			text.WriteString(part)

			if err := onMessage(MessageKindAssistantPartialMessage, []byte(part), c.assist.clock.Now().UTC()); err != nil {
				return nil, trace.Wrap(err)
			}
		}

		// write an assistant message to memory and persistent storage
		textS := text.String()
		c.chat.Insert(openai.ChatMessageRoleAssistant, textS)
		protoMsg := &assist.CreateAssistantMessageRequest{
			ConversationId: c.ConversationID,
			Username:       c.Username,
			Message: &assist.AssistantMessage{
				Type:        string(MessageKindAssistantMessage),
				Payload:     textS,
				CreatedTime: timestamppb.New(c.assist.clock.Now().UTC()),
			},
		}

		if err := c.assistService.CreateAssistantMessage(ctx, protoMsg); err != nil {
			return nil, trace.Wrap(err)
		}
	case *model.CompletionCommand:
		tokensUsed = message.TokensUsed
		payload := commandPayload{
			Command: message.Command,
			Nodes:   message.Nodes,
			Labels:  message.Labels,
		}

		payloadJson, err := json.Marshal(payload)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		msg := &assist.CreateAssistantMessageRequest{
			ConversationId: c.ConversationID,
			Username:       c.Username,
			Message: &assist.AssistantMessage{
				Type:        string(MessageKindCommand),
				Payload:     string(payloadJson),
				CreatedTime: timestamppb.New(c.assist.clock.Now().UTC()),
